options.dotDiagram:
digraph change_pipeline {
  rankdir=LR; splines=ortho; nodesep=0.3; ranksep=0.45; pad=0.1; bgcolor="transparent";
  node [shape=box, style="rounded,filled", width=1.9, height=0.9, fontsize=13,
        color="#2c313c", fillcolor="#6b7280", fontcolor="#e5e7eb"];
  edge [color="#4b5563", penwidth=1.6, arrowsize=0.8];
  pushed [label="pushed"]; pr_open [label="PR open"]; checks_green [label="checks"];
  merged [label="merged"]; applied [label="applied"]; live [label="live"];
  pushed -> pr_open -> checks_green -> merged -> applied -> live;
}
